      "dialogue": [
        {
          "speaker": "麦克",
          "zh": "请问，你贵姓？",
          "py": "Qǐngwèn, nǐ guìxìng?",
          "vi": "Xin hỏi, bạn họ gì?"
        },
        {
          "speaker": "张东",
          "zh": "我姓张。",
          "py": "Wǒ xìng Zhāng.",
          "vi": "Tôi họ Trương."
        },
        {
          "speaker": "麦克",
          "zh": "你叫什么名字？",
          "py": "Nǐ jiào shénme míngzi?",
          "vi": "Bạn tên là gì?"
        },
        {
          "speaker": "张东",
          "zh": "我叫张东。你是哪国人？",
          "py": "Wǒ jiào Zhāng Dōng. Nǐ shì nǎ guó rén?",
          "vi": "Tôi tên Trương Đông. Bạn là người nước nào?"
        },
        {
          "speaker": "麦克",
          "zh": "我是美国人。你学习什么？",
          "py": "Wǒ shì Měiguó rén. Nǐ xuéxí shénme?",
          "vi": "Tôi là người Mỹ. Bạn học gì?"
        },
        {
          "speaker": "张东",
          "zh": "我学习汉语。汉语难吗？",
          "py": "Wǒ xuéxí Hànyǔ. Hànyǔ nán ma?",
          "vi": "Tôi học tiếng Hán. Tiếng Hán khó không?"
        },
        {
          "speaker": "麦克",
          "zh": "汉字很难，发音不太难。",
          "py": "Hànzì hěn nán, fāyīn bú tài nán.",
          "vi": "Chữ Hán rất khó, phát âm không khó lắm."
        }
      ],
