      "dialogue": [
        {
          "speaker": "买者",
          "zh": "买苹果。一斤多少钱？",
          "py": "Mǎi píngguǒ. Yì jīn duōshao qián?",
          "vi": "Tôi mua táo. Bao nhiêu tiền một cân?"
        },
        {
          "speaker": "售货员",
          "zh": "三块。",
          "py": "Sān kuài.",
          "vi": "3 tệ."
        },
        {
          "speaker": "买者",
          "zh": "太贵了。两块五吧。",
          "py": "Tài guì le. Liǎng kuài wǔ ba.",
          "vi": "Đắt quá. 2 tệ rưỡi nhé."
        },
        {
          "speaker": "售货员",
          "zh": "你要几斤？",
          "py": "Nǐ yào jǐ jīn?",
          "vi": "Bạn mua mấy cân?"
        },
        {
          "speaker": "买者",
          "zh": "我买五斤。",
          "py": "Wǒ mǎi wǔ jīn.",
          "vi": "Tôi mua 5 cân."
        },
        {
          "speaker": "售货员",
          "zh": "还要别的吗？",
          "py": "Hái yào bié de ma?",
          "vi": "Còn mua gì khác không?"
        },
        {
          "speaker": "买者",
          "zh": "橘子多少钱一斤？",
          "py": "Júzi duōshao qián yì jīn?",
          "vi": "Quýt bao nhiêu tiền một cân?"
        },
        {
          "speaker": "售货员",
          "zh": "两块。",
          "py": "Liǎng kuài.",
          "vi": "2 tệ một cân."
        },
        {
          "speaker": "买者",
          "zh": "要两斤。一共多少钱？",
          "py": "Yào liǎng jīn. Yígòng duōshao qián?",
          "vi": "Lấy 2 cân. Tổng cộng bao nhiêu tiền?"
        },
        {
          "speaker": "售货员",
          "zh": "一共十六块五毛。",
          "py": "Yígòng shíliù kuài wǔ máo.",
          "vi": "Tổng cộng 16 tệ 5 hào."
        }
      ],
