      "dialogue": [
        {
          "speaker": "海关",
          "zh": "先生，这个箱子是您的吗？",
          "py": "Xiānsheng, zhè ge xiāngzi shì nín de ma?",
          "vi": "Thưa ngài, chiếc vali này là của ngài phải không?"
        },
        {
          "speaker": "大卫",
          "zh": "是我的。",
          "py": "Shì wǒ de.",
          "vi": "Là của tôi."
        },
        {
          "speaker": "海关",
          "zh": "请打开看看。这里边是什么？",
          "py": "Qǐng dǎkāi kànkan. Zhè lǐbian shì shénme?",
          "vi": "Xin mở ra kiểm tra. Bên trong là gì thế?"
        },
        {
          "speaker": "大卫",
          "zh": "都是日用品，还有两瓶药。",
          "py": "Dōu shì rìyòngpǐn, hái yǒu liǎng píng yào.",
          "vi": "Đều là đồ dùng sinh hoạt, còn có hai lọ thuốc nữa."
        },
        {
          "speaker": "海关",
          "zh": "这是不是中药？",
          "py": "Zhè shì bú shì zhōngyào?",
          "vi": "Đây có phải là thuốc đông y không?"
        },
        {
          "speaker": "大卫",
          "zh": "这不是中药，这是西药。",
          "py": "Zhè bú shì zhōngyào, zhè shì xīyào.",
          "vi": "Đây không phải thuốc đông y, đây là thuốc tây."
        }
      ],
      "grammar": [
        "Động từ 有 / 没有: Diễn tả sự tồn tại và sở hữu (phủ định bắt buộc dùng 没, không dùng 不)",
        "Câu hỏi chính phản với 是: 是不是 (có phải là... không)",
        "Từ vựng đối lập 中药 (Đông y) và 西药 (Tây y): Kết hợp với câu hỏi chính phản 是不是 để xác nhận thông tin (这是不是中药？这不是中药，这是西药)."
      ]
