          "py": "Wǒ yě cháng qù. Yǒushíhòu jiè shū, yǒushíhòu shàngwǎng chá zīliào, dàn bù cháng zài nàr kàn shū. Wǒ zǒng zài sùshè kàn shū.",
          "vi": "Tớ cũng thường đi. Có khi mượn sách, có khi lên mạng tra tài liệu, nhưng không thường đọc sách ở đấy. Tớ toàn đọc sách ở ký túc xá thôi.",
          "section": "（一）你常去图书馆吗？ (Bạn thường đến thư viện không?)"
