          "py": "Cóng zhèr yìzhí wǎng qián zǒu, dào le shízì lùkǒu wǎng yòu guǎi, zài wǎng qián zǒu liǎngbǎi mǐ, mǎlù duìmiàn jiù shì Gùgōng.",
