      "dialogue": [
        {
          "speaker": "罗兰",
          "zh": "玛丽，你看，那位中国姑娘太极拳打得真好！",
          "py": "Mǎlì, nǐ kàn, nà wèi Zhōngguó gūniang tàijíquán dǎ de zhēn hǎo!",
          "vi": "Mary, cậu nhìn kìa, cô gái Trung Quốc kia đánh Thái Cực Quyền đẹp thật đấy!",
          "section": "（一）她学得很好 (Cô ấy học rất giỏi)"
        },
        {
          "speaker": "玛丽",
          "zh": "是啊，她动作很优美，学得很认真。",
          "py": "Shì a, tā dòngzuò hěn yōuměi, xué de hěn rènzhēn.",
          "vi": "Đúng thế, động tác của cô ấy rất uyển chuyển, học rất chăm chỉ.",
          "section": "（一）她学得很好 (Cô ấy học rất giỏi)"
        },
        {
          "speaker": "罗兰",
          "zh": "她汉语也说得很好，发音很标准。",
          "py": "Tā Hànyǔ yě shuō de hěn hǎo, fāyīn hěn biāozhǔn.",
          "vi": "Cô ấy nói tiếng Hán cũng rất giỏi, phát âm cực kỳ chuẩn.",
          "section": "（一）她学得很好 (Cô ấy học rất giỏi)"
        },
        {
          "speaker": "玛丽",
          "zh": "她每天早上起得很早，在操场一边散步一边练太极拳，学习非常努力。",
          "py": "Tā měitiān zǎoshang qǐ de hěn zǎo, zài cāochǎng yìbiān sànbù yìbiān liàn tàijíquán, xuéxí fēicháng nǔlì.",
          "vi": "Sáng nào cô ấy cũng dậy rất sớm, vừa đi dạo trên sân vừa luyện Thái Cực Quyền, học tập vô cùng nỗ lực.",
          "section": "（一）她学得很好 (Cô ấy học rất giỏi)"
        },
        {
          "speaker": "老师",
          "zh": "麦克，你写毛笔字写得怎么样？",
          "py": "Màikè, nǐ xiě máobǐzì xiě de zěnmeyàng?",
          "vi": "Mike, em viết chữ bút lông (thư pháp) thế nào rồi?",
          "section": "（二）谈中国书法 (Nói về thư pháp Trung Quốc)"
        },
        {
          "speaker": "麦克",
          "zh": "老师，我写得不好，写得很慢。",
          "py": "Lǎoshī, wǒ xiě de bù hǎo, xiě de hěn màn.",
          "vi": "Thưa thầy, em viết chưa tốt, viết rất chậm ạ.",
          "section": "（二）谈中国书法 (Nói về thư pháp Trung Quốc)"
        },
        {
          "speaker": "老师",
          "zh": "没关系，刚开始学都这样。只要坚持练，就会写得越来越好。",
          "py": "Méi guānxi, gāng kāishǐ xué dōu zhèyàng. Zhǐyào jiānchí liàn, jiù huì xiě de yuè lái yuè hǎo.",
          "vi": "Không sao cả, mới bắt đầu học ai cũng vậy. Chỉ cần kiên trì luyện tập, em sẽ viết ngày càng đẹp hơn thôi.",
          "section": "（二）谈中国书法 (Nói về thư pháp Trung Quốc)"
        }
      ],
      "grammar": [
        "Bổ ngữ trạng thái / mức độ với 得: Động từ + 得 + Tính từ / Cụm miêu tả (她学得很好, 跑得很快)",
        "Quy tắc khi động từ mang tân ngữ: V + O + V + 得 + Cụm miêu tả (她说汉语说得很好)",
        "Dạng phủ định của bổ ngữ trạng thái: V + 得 + 不 + Tính từ (跑得不快)"
      ]
